    # 七键与 stp-decode（stp-check）完全一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, max_frame = (
        validate_stp_check_config(
            {key: config[key] for key in STP_CHECK_CONFIG_KEYS}
        )
    )
    dhcp = config["dhcp"]
    if not isinstance(dhcp, dict) or frozenset(dhcp) != DHCP_KEYS:
        raise InvalidInput("bad dhcp")
    trusted_ports = dhcp["trusted_ports"]
    if not isinstance(trusted_ports, list):
        raise InvalidInput("bad dhcp trusted_ports")
    name_set = {port["name"] for port in ports}
    for name in trusted_ports:
        if not isinstance(name, str) or name not in name_set:
            raise InvalidInput("bad dhcp trusted port")
    if len(set(trusted_ports)) != len(trusted_ports):  # 端口名不重复
        raise InvalidInput("bad dhcp trusted_ports")
    binding_capacity = dhcp["binding_capacity"]
    if not isinstance(binding_capacity, dict):
        raise InvalidInput("bad dhcp binding_capacity")
    if not binding_capacity:  # 至少一个 VLAN 容量项
        raise InvalidInput("bad dhcp binding_capacity")
    capacity = {}
    for key, value in binding_capacity.items():
        if not _valid_vlan_id(key) or not isinstance(value, int) or value < 0:
            raise InvalidInput("bad dhcp binding_capacity")
        capacity[key] = value
    max_lease = dhcp["max_lease"]
    if not _is_int(max_lease) or max_lease <= 0:
        raise InvalidInput("bad dhcp max_lease")
    return (
        bridges, links, delay, bridge, ports, age, max_frame,
        tuple(trusted_ports), capacity, max_lease,
    )


def _ipv4_octets(value):
    """4 字节 IPv4 地址点分十进制。"""
    return ".".join(str(octet) for octet in value)


def _parse_dhcp_outer(raw, ethertype_offset):
    """定位单层 IPv4 上未分片的 UDP/BOOTP 报文并做外层校验。

    返回 None：帧并非形似 DHCP（非 IPv4、非 UDP、分片、头长/校验/端口不
    符），调用方完全沿用既有 VLAN、STP、帧合法性与转发语义；
    返回 ("invalid",)：外层已形似 DHCP（未分片 UDP、目的端口 67/68），
    但协议长度或 IPv4 首部校验和非法，调用方固定输出 malformed_dhcp；
    返回 ("bootp", src_octets, dst_octets, bootp_msg)：按 IPv4 总长度
    截取的 BOOTP 报文，交由后续 BOOTP/DHCP 校验。
    """
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 20:
        return None
    if payload[0] >> 4 != 4:
        return None
    ihl = payload[0] & 0x0F
    if ihl < 5:
        return None
    header_len = ihl * 4
    if len(payload) < header_len:
        return None
    fragment_word = (payload[6] << 8) | payload[7]
    # 任何分片（MF 或偏移非零）都不识别为 DHCP
    if fragment_word & 0x3FFF:
        return None
    if payload[9] != IP_PROTOCOL_UDP:
        return None
    total_length = (payload[2] << 8) | payload[3]
    if total_length < header_len + 8 or total_length > len(payload):
        # 协议长度容纳不了 UDP 头或超过实际载荷：形似 DHCP 前须先确认端口
        return None
    udp_start = header_len
    dst_port = (payload[udp_start + 2] << 8) | payload[udp_start + 3]
    if dst_port not in (BOOTP_CLIENT_PORT, BOOTP_SERVER_PORT):
        return None
    # 自此帧“形似 DHCP”：任何非法均为 malformed_dhcp
    if _internet_checksum(payload[:header_len]) != 0:
        return ("invalid",)
    udp_len = (payload[udp_start + 4] << 8) | payload[udp_start + 5]
    if udp_len < 8 or header_len + udp_len > total_length:
        return ("invalid",)
    bootp_msg = bytes(payload[udp_start + 8:total_length])
    if udp_len != 8 and udp_len - 8 > len(bootp_msg):
        return ("invalid",)
    if udp_len >= 8 + BOOTP_MIN_LEN:
        bootp_msg = bootp_msg[:udp_len - 8]
    src_octets = bytes(payload[12:16])
    dst_octets = bytes(payload[16:20])
    return ("bootp", src_octets, dst_octets, bootp_msg)


def _parse_dhcp(bootp_msg):
    """对已截取的 BOOTP 报文做 BOOTP 定长字段、magic cookie 与关键选项校验。

    返回 ("invalid",) 或 ("ok", info)；info 为 dict，键固定：
    op、msg_type、xid、chaddr（点分 MAC 小写串）、ciaddr/yiaddr/siaddr
    （点分 IPv4 串）、lease（选项 51 正整数或 None）。
    选项须恰含一个 53，51 至多一个；未知选项忽略，选项区须以 END 闭合且
    字节闭合；PAD 可出现在任意位置。
    """
    if len(bootp_msg) < BOOTP_MIN_LEN:
        return ("invalid",)
    op = bootp_msg[0]
    if op not in (BOOTP_OP_REQUEST, BOOTP_OP_REPLY):
        return ("invalid",)
    hlen = bootp_msg[2]
    if hlen != 6:  # chaddr 以以太网 6 字节硬件地址为准
        return ("invalid",)
    hops = bootp_msg[3]
    if hops != 0:
        return ("invalid",)
    # secs/flags（4..8）不约束；xid 为 4..8
    xid = int.from_bytes(bootp_msg[4:8], "big")
    ciaddr = bytes(bootp_msg[12:16])
    yiaddr = bytes(bootp_msg[16:20])
    siaddr = bytes(bootp_msg[20:24])
    chaddr = bytes(bootp_msg[28:34])
    if not any(chaddr) or chaddr[0] & 1:  # 客户端 MAC 须为非零单播
        return ("invalid",)
    if any(bootp_msg[34:44]):  # chaddr 余 10 字节（全硬件地址长度）须为零
        return ("invalid",)
    sname = bootp_msg[44:108]
    file_field = bootp_msg[108:236]
    cookie_end = BOOTP_FIXED_LEN + 4
    if bootp_msg[BOOTP_FIXED_LEN:cookie_end] != BOOTP_MAGIC_COOKIE:
        return ("invalid",)
    options_region = bootp_msg[cookie_end:]
    msg_types = []
    lease = None
    index = 0
    saw_end = False
    while index < len(options_region):
        code = options_region[index]
        if code == 0:  # PAD
            index += 1
            continue
        if code == DHCP_OPT_END:
            saw_end = True
            if any(options_region[index + 1:]):  # END 后只允许缺省（无字节）
                return ("invalid",)
            break
        if index + 2 > len(options_region):
            return ("invalid",)
        length = options_region[index + 1]
        value_start = index + 2
        value_end = value_start + length
        if value_end > len(options_region):
            return ("invalid",)
        value = options_region[value_start:value_end]
        if code == DHCP_OPT_MSG_TYPE:
            if length != 1 or value[0] not in (
                DHCP_CLIENT_MESSAGES | DHCP_SERVER_MESSAGES
            ):
                return ("invalid",)
            msg_types.append(value[0])
        elif code == DHCP_OPT_LEASE_TIME:
            if length != 4:
                return ("invalid",)
            candidate = int.from_bytes(value, "big")
            if candidate == 0:  # 租期须为正整数（0xffffffff 等合法）
                return ("invalid",)
            lease = candidate
        # 其余选项（含 54 server-id）不做语义约束
        index = value_end
    if not saw_end or len(msg_types) != 1:
        return ("invalid",)
    msg_type = msg_types[0]
    if op == BOOTP_OP_REQUEST and msg_type not in DHCP_CLIENT_MESSAGES:
        return ("invalid",)
    if op == BOOTP_OP_REPLY and msg_type not in DHCP_SERVER_MESSAGES:
        return ("invalid",)
    # 客户端报文须发往服务器端口 67；服务器报文须发往客户端端口 68，
    # 由调用方结合外层目的端口判定，此处只做地址字段与 sname/file 校验：
    # sname/file 须为零填充（本实现不解析引导文件名/服务器名）
    if any(sname) or any(file_field):
        return ("invalid",)
    return (
        "ok",
        {
            "op": op,
            "msg_type": msg_type,
            "xid": xid,
            "chaddr": _format_mac(chaddr),
            "ciaddr": _ipv4_octets(ciaddr),
            "yiaddr": _ipv4_octets(yiaddr),
            "siaddr": _ipv4_octets(siaddr),
            "lease": lease,
        },
    )


def _parse_dhcp_frame(raw, ethertype_offset):
    """原始帧统一入口：返回 None（非形似 DHCP）、("invalid",)
    （形似 DHCP 但报文非法）或 ("ok", info, dst_port)。"""
    outer = _parse_dhcp_outer(raw, ethertype_offset)
    if outer is None:
        return None
    if outer[0] == "invalid":
        return ("invalid",)
    _, src_octets, dst_octets, bootp_msg = outer
    payload = raw[ethertype_offset + 2:-4]
    udp_start = (payload[0] & 0x0F) * 4
    dst_port = (payload[udp_start + 2] << 8) | payload[udp_start + 3]
    parsed = _parse_dhcp(bootp_msg)
    if parsed[0] == "invalid":
        return ("invalid",)
    info = parsed[1]
    info["src_ip"] = _ipv4_octets(src_octets)
    info["dst_ip"] = _ipv4_octets(dst_octets)
    info["dst_port"] = dst_port
    # op 与 UDP 目的端口方向必须一致：客户端发往 67，服务器发往 68
    if info["op"] == BOOTP_OP_REQUEST and dst_port != BOOTP_SERVER_PORT:
        return ("invalid",)
    if info["op"] == BOOTP_OP_REPLY and dst_port != BOOTP_CLIENT_PORT:
        return ("invalid",)
    return ("ok", info)


def dhcp_snoop_work(ports, events, limit):
    """dhcp-snoop-decode 工作量无副作用预演：逐事件累计
    1 + 端口数 P + 处理前活动绑定数 B（初始 0）；仅按事件序模拟绑定的
    增加（合法 ACK）、老化（expires<=t）、NAK/RELEASE/RELEASE 端口退出
    造成的删除。容量、冲突等不改变绑定数的事件与正式仿真同形：活动绑定
    数与正式仿真逐事件一致，故预演可仅跟踪绑定键的增删与过期。等于上限
    合法，首次超过抛 DhcpWorkLimit。
    """
    P = len(ports)
    # (vlan, ip) -> expires；预演只需过期时刻与计数
    bindings = {}

    def purge(t):
        for key in [key for key, expires in bindings.items() if expires <= t]:
            del bindings[key]

    work = 0
    for item in events:
        t = item[1]
        purge(t)
        work += 1 + P + len(bindings)
        if work > limit:
            raise DhcpWorkLimit
        if item[0] != "frame":
            continue
        raw = item[3]
        ethertype_offset = 16 if raw[12:14] == FRAME_DECODE_TAG else 12
        if (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        ) != IPV4_ETHER_TYPE:
            continue
        parsed = _parse_dhcp_frame(raw, ethertype_offset)
        if parsed is None or parsed[0] == "invalid":
            continue
        info = parsed[1]
        if raw[12:14] == FRAME_DECODE_TAG:
            vlan = (raw[14] << 8 | raw[15]) & 0x0FFF
        else:
            vlan = None  # 仅用于预演计数的占位，实际 VLAN 在仿真中定
        # 预演无法不读端口配置而区分准入/STP；绑定增删计数的口径以“通过
        # 帧合法性、VLAN 准入与 STP forwarding 的 DHCP 帧”为准，与正式
        # 仿真保持一致需要端口配置，故预演在仿真函数内部完成（见
        # _dhcp_snoop_work_preview）。
    return None


def _dhcp_snoop_work_preview(
    bridges, links, delay, bridge_name, ports, age, max_frame,
    trusted_set, capacity, max_lease, events, limit,
):
    """与正式仿真同构的无副作用预演：完整重放帧合法性、VLAN 准入、STP
    状态及 DHCP 绑定机（但不产生结果/统计），逐事件计费
    1+P+处理前活动绑定数，等于上限合法，首次超过抛 DhcpWorkLimit。
    """
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    P = len(ports)
    previous = {}
    since = {}
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"
        return True, state

    # 绑定键 -> [expires, mac, vlan, port]；预演只需 expires 计数，但增删
    # 判定（冲突/容量/NAK/RELEASE）需与正式仿真同形
    bindings = {}
    requests = {}  # (vlan, xid, chaddr) -> access_port

    def purge(t):
        for key in [key for key, value in bindings.items() if value[0] <= t]:
            del bindings[key]

    converge(0)
    work = 0
    for item in events:
        t = item[1]
        purge(t)
        work += 1 + P + len(bindings)
        if work > limit:
            raise DhcpWorkLimit
        if item[0] == "link":
            _, _, lid, up = item
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            left = old_forwarding - forwarding_ports(t)
            if left:
                for key in [
                    key for key, value in bindings.items() if value[3] in left
                ]:
                    del bindings[key]
            continue
        _, _, port_name, raw = item
        length = len(raw)
        if length < FRAME_CHECK_RUNT_LENGTH or length > max_frame:
            continue
        if raw[-4:] != (
            zlib.crc32(raw[:-4]) & 0xFFFFFFFF
        ).to_bytes(4, "little"):
            continue
        if raw[12:14] == FRAME_DECODE_TAG:
            vlan = (raw[14] << 8) | raw[15]
            vlan &= 0x0FFF
            ingress = by_name[port_name]
            if ingress["mode"] == "access" or vlan not in ingress["allowed"]:
                continue
        else:
            vlan = by_name[port_name]["pvid"]
        _, state = port_status(port_name, t)
        if state != "forwarding":
            continue
        ethertype_offset = 16 if raw[12:14] == FRAME_DECODE_TAG else 12
        if (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        ) != IPV4_ETHER_TYPE:
            continue
        parsed = _parse_dhcp_frame(raw, ethertype_offset)
        if parsed is None or parsed[0] == "invalid":
            continue
        info = parsed[1]
        mtype = info["msg_type"]
        chaddr = info["chaddr"]
        xid = info["xid"]
        if mtype in (DHCP_MSG_DISCOVER, DHCP_MSG_REQUEST):
            requests[(vlan, xid, chaddr)] = port_name
            continue
        if mtype == DHCP_MSG_RELEASE:
            for key, value in [
                (key, value)
                for key, value in bindings.items()
                if value[1] == chaddr
                and value[2] == vlan
                and value[3] == port_name
            ]:
                del bindings[key]
            continue
        if mtype not in (DHCP_MSG_ACK, DHCP_MSG_NAK):
            continue
        if port_name not in trusted_set:
            continue
        req_key = (vlan, xid, chaddr)
        if req_key not in requests:
            continue
        if mtype == DHCP_MSG_NAK:
            del requests[req_key]
            continue
        # ACK
        yiaddr = info["yiaddr"]
        if yiaddr == "0.0.0.0":
            continue
        octets = tuple(int(part) for part in yiaddr.split("."))
        if not (1 <= octets[0] <= 223 and octets[0] != 127):
            continue
        lease = info["lease"]
        if lease is None:
            continue
        key = (vlan, yiaddr)
        existing = bindings.get(key)
        if existing is not None and existing[1] != chaddr:
            continue  # binding_conflict：不建绑定
        limit_v = capacity.get(vlan)
        if limit_v is not None and existing is None and len(
            [value for value in bindings.values() if value[2] == vlan]
        ) >= limit_v:
            continue  # binding_full：不建绑定
        expiry = t + min(lease, max_lease)
        bindings[key] = [expiry, chaddr, vlan, port_name]
        del requests[req_key]


def dhcp_snoop_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame,
    trusted_ports, capacity, max_lease, events, observer=None,
):
    """在 stp-decode 转发/学习/统计语义上增加 DHCPv4 Snooping。

    非 DHCP 帧完全沿用既有 VLAN、STP、帧合法性与转发语义。形似 DHCP 但
    IPv4/UDP/BOOTP/DHCP 任一层非法时固定 malformed_dhcp、空 ports、计
    drop，不学习 FDB、不记录请求或绑定。非受信任端口发来的
    OFFER/ACK/NAK 固定 untrusted_server 并丢弃。

    合法客户端 DISCOVER/REQUEST 按 (vlan, xid, chaddr) 记录接入口；仅受
    信任端口返回且 xid、chaddr、VLAN 与待处理请求匹配的 ACK 才按
    yiaddr、客户端 MAC、VLAN、接入口与租期（超过 max_lease 截断）建立或
    刷新绑定；每事件先老化 expires<=t 的绑定；NAK 清除匹配请求；RELEASE
    仅在来源端口、MAC、VLAN 均匹配时删除绑定。活动 IP 已被同 VLAN 其他
    MAC 占用时 binding_conflict 丢弃；ACK 合法但该 VLAN 绑定数达容量上
    限时 binding_full，数据面仍按既有规则转发但不建绑定。

    每个结果项固定键序 t/class/action/ports/snoop；末态另出 bindings
    （vlan/ip/mac/port/expires，按 vlan、IP 数值、MAC、端口排序）与每端口
    DHCP 分类计数 snoop_counters。observer 语义同 stp-check。
    """
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [port, seen]
    # (vlan, ip) -> {"mac", "port", "expires"}
    bindings = {}
    # (vlan, xid, chaddr) -> access_port
    requests = {}
    trusted_set = set(trusted_ports)
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    snoop_counters = {
        port["name"]: {
            "malformed_dhcp": 0,
            "untrusted_server": 0,
            "discover": 0,
            "request": 0,
            "offer": 0,
            "ack": 0,
            "nak": 0,
            "release": 0,
            "decline": 0,
            "inform": 0,
            "binding_conflict": 0,
            "binding_full": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    if observer is not None:
        observer["items"] = []

    previous = {}
    since = {}
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "drop" and "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"
        return True, state

    def eligible_names(t, vlan, ingress):
        return [
            port["name"]
            for port in ports
            if vlan in port["allowed"]
            and port["name"] != ingress
            and port_status(port["name"], t) == (True, "forwarding")
        ]

    def purge_bindings(t):
        for key in [
            key
            for key, entry in bindings.items()
            if entry["expires"] <= t
        ]:
            del bindings[key]

    def emit(t, cls, action, out_ports, snoop, ingress=None, vlan=None):
        """统一记录结果项（固定键序 t/class/action/ports/snoop）与统计。"""
        out = []
        for name in out_ports:
            port_stats[name]["tx"] += 1
            if vlan is not None:
                vlan_stats[vlan]["tx"] += 1
            out.append(
                {
                    "name": name,
                    "vlan": (
                        None
                        if vlan in by_name[name]["untagged"]
                        else vlan
                    ),
                }
            )
        entry = {
            "t": t,
            "class": cls,
            "action": action,
            "ports": out,
            "snoop": snoop,
        }
        results.append(entry)
        if observer is not None:
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )
        return entry

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        purge_bindings(t)  # 每个事件前先老化到期绑定
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            left_forwarding = old_forwarding - forwarding_ports(t)
            for name in left_forwarding:
                for key in [k for k, (p, _) in fdb.items() if p == name]:
                    del fdb[key]
                # 端口退出 forwarding：清除该口上的绑定与待处理请求
                for bkey in [
                    bkey
                    for bkey, entry in bindings.items()
                    if entry["port"] == name
                ]:
                    del bindings[bkey]
                for rkey in [
                    rkey for rkey, port in requests.items() if port == name
                ]:
                    del requests[rkey]
            if observer is not None:
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, raw = item
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            tag = tci & 0x0FFF
            ethertype_offset = 16
        else:
            tag = None
            ethertype_offset = 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        length = len(raw)
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif raw[-4:] != (
            zlib.crc32(raw[:-4]) & 0xFFFFFFFF
        ).to_bytes(4, "little"):
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":
            port_stats[port_name]["drop"] += 1
            emit(t, cls, "drop", [], None)
            continue
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:
            port_stats[port_name]["drop"] += 1
            emit(t, cls, "drop", [], None)
            continue
        vlan_stats[vlan]["rx"] += 1
        _, state = port_status(port_name, t)
        # DHCP 识别仅在 forwarding 状态进行；discarding/learning 与非
        # forwarding 端口收到的形似 DHCP 帧不触发 malformed 分类，完全
        # 沿用既有语义（learning 学习 FDB 但不转发）
        dhcp_info = None
        if state == "forwarding" and ethertype == IPV4_ETHER_TYPE:
            dhcp_info = _parse_dhcp_frame(raw, ethertype_offset)
        if dhcp_info is not None and dhcp_info[0] == "invalid":
            # 形似 DHCP 但报文非法：丢弃，不学习 FDB、不记录请求或绑定
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
            snoop_counters[port_name]["malformed_dhcp"] += 1
            snoop = {"classification": "malformed_dhcp"}
            emit(
                t, cls, "malformed_dhcp", [], snoop,
                ingress=port_name, vlan=vlan,
            )
            continue
        egress = []
        action = "drop"
        snoop = None
        if state == "learning":
            fdb[(vlan, src)] = [port_name, t]
        elif state == "forwarding":
            fdb[(vlan, src)] = [port_name, t]
            if dhcp_info is not None:
                snoop = _dhcp_handle(
                    t, port_name, vlan, raw, dst, dhcp_info[1],
                    bindings, requests, trusted_set, capacity, max_lease,
                    snoop_counters,
                )
                action = snoop["action"]
                if action in ("untrusted_server", "binding_conflict"):
                    # 控制面拒绝：数据面丢弃
                    egress = []
                elif action == "binding_full":
                    # 容量满：ACK 仍按既有数据面转发
                    egress = _dhcp_data_egress(
                        t, port_name, vlan, dst, fdb, by_name, eligible_names,
                    )
                elif action in (
                    "discover", "request", "offer", "ack", "nak",
                    "release", "decline", "inform",
                ):
                    egress = _dhcp_data_egress(
                        t, port_name, vlan, dst, fdb, by_name, eligible_names,
                    )
            else:
                is_group = int(dst[:2], 16) & 1
                eligible = eligible_names(t, vlan, port_name)
                if is_group:
                    egress = eligible
                    action = "flood"
                else:
                    hit = fdb.get((vlan, dst))
                    if hit is not None and hit[0] != port_name:
                        target = hit[0]
                        target_up, target_state = port_status(target, t)
                        if (
                            target_up
                            and target_state == "forwarding"
                            and vlan in by_name[target]["allowed"]
                        ):
                            egress = [target]
                            action = "unicast"
                    elif hit is None:
                        egress = eligible
                        action = "flood"
        if not egress and action not in (
            "untrusted_server", "malformed_dhcp"
        ):
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        if action == "untrusted_server":
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        emit(
            t, cls, action, egress, snoop,
            ingress=port_name, vlan=vlan,
        )
    port_order = {port["name"]: index for index, port in enumerate(ports)}
    bindings_out = []
    for (vlan, ip), entry in sorted(
        bindings.items(),
        key=lambda item: (
            item[0][0],
            tuple(int(part) for part in item[0][1].split(".")),
            tuple(int(part, 16) for part in item[1]["mac"].split(":")),
            port_order[item[1]["port"]],
        ),
    ):
        bindings_out.append(
            {
                "vlan": vlan,
                "ip": ip,
                "mac": entry["mac"],
                "port": entry["port"],
                "expires": entry["expires"],
            }
        )
    output = {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
        "bindings": bindings_out,
        "snoop_counters": [
            {"name": port["name"],
             **snoop_counters[port["name"]]}
            for port in ports
        ],
    }
    return output


def _dhcp_data_egress(t, port_name, vlan, dst, fdb, by_name, eligible_names):
    """DHCP 帧的数据面转发：广播（DISCOVER/REQUEST/OFFER 广播等）泛洪；
    单播按 FDB 命中转发，未命中泛洪。完全沿用既有语义。"""
    is_group = int(dst[:2], 16) & 1
    eligible = eligible_names(t, vlan, port_name)
    if is_group:
        return eligible
    hit = fdb.get((vlan, dst))
    if hit is not None and hit[0] != port_name:
        return [hit[0]]
    return eligible


def _dhcp_handle(
    t, port_name, vlan, raw, dst, info, bindings, requests, trusted_set,
    capacity, max_lease, snoop_counters,
):
    """处理一帧已通过帧合法性/VLAN 准入/STP forwarding 的 DHCP 报文，
    返回 {"action", ...} snoop 详情 dict（其 action 同时作为结果 action）。
    所有控制面状态修改在此完成；数据面转发由调用方按 action 决定。
    """
    mtype = info["msg_type"]
    xid = info["xid"]
    chaddr = info["chaddr"]
    req_key = (vlan, xid, chaddr)

    def detail(action, **extra):
        result = {"action": action, "msg_type": mtype, "xid": xid}
        for key in (
            "chaddr", "ciaddr", "yiaddr", "siaddr", "lease", "truncated_lease"
        ):
            pass
        result.update(extra)
        return result

    if info["op"] == BOOTP_OP_REPLY:
        # 服务器到客户端：OFFER/ACK/NAK 仅允许来自受信任端口
        if port_name not in trusted_set:
            snoop_counters[port_name]["untrusted_server"] += 1
            return {
                "action": "untrusted_server",
                "msg_type": mtype,
                "xid": xid,
                "chaddr": chaddr,
                "yiaddr": info["yiaddr"],
            }
        if mtype == DHCP_MSG_OFFER:
            snoop_counters[port_name]["offer"] += 1
            return {
                "action": "offer",
                "msg_type": mtype,
                "xid": xid,
                "chaddr": chaddr,
                "yiaddr": info["yiaddr"],
            }
        if mtype == DHCP_MSG_NAK:
            matched = requests.pop(req_key, None) is not None
            snoop_counters[port_name]["nak"] += 1
            return {
                "action": "nak",
                "msg_type": mtype,
                "xid": xid,
                "chaddr": chaddr,
                "matched": matched,
            }
        # ACK：须匹配待处理请求（xid、chaddr、VLAN、接入口）
        access_port = requests.get(req_key)
        if access_port is None or access_port != port_name:
            # 服务器从受信任口返回但无匹配请求：按既有数据面转发，不建绑定
            snoop_counters[port_name]["ack"] += 1
            return {
                "action": "ack",
                "msg_type": mtype,
                "xid": xid,
                "chaddr": chaddr,
                "yiaddr": info["yiaddr"],
                "lease": info["lease"],
                "bound": False,
            }
        yiaddr = info["yiaddr"]
        lease = info["lease"]
        octets = tuple(int(part) for part in yiaddr.split("."))
        valid_yiaddr = 1 <= octets[0] <= 223 and octets[0] != 127
        if yiaddr == "0.0.0.0" or not valid_yiaddr or lease is None:
            # 无有效地址或租期的 ACK：不建绑定，数据面仍转发
            snoop_counters[port_name]["ack"] += 1
            return {
                "action": "ack",
                "msg_type": mtype,
                "xid": xid,
                "chaddr": chaddr,
                "yiaddr": yiaddr,
                "lease": lease,
                "bound": False,
            }
        ip_key = (vlan, yiaddr)
        existing = bindings.get(ip_key)
        if existing is not None and existing["mac"] != chaddr:
            # 活动 IP 已被同 VLAN 其他 MAC 占用：binding_conflict，丢弃
            snoop_counters[port_name]["binding_conflict"] += 1
            return {
                "action": "binding_conflict",
                "msg_type": mtype,
                "xid": xid,
                "chaddr": chaddr,
                "yiaddr": yiaddr,
                "owner_mac": existing["mac"],
            }
        truncated = min(lease, max_lease)
        vlan_count = sum(1 for entry in bindings.values() if True) if False else None
        per_vlan = sum(
            1 for (bvlan, _), entry in bindings.items() if bvlan == vlan
        )
        cap = capacity.get(vlan)
        if (
            existing is None
            and cap is not None
            and per_vlan >= cap
        ):
            # 新绑定超过容量：binding_full，ACK 仍转发但不建绑定
            snoop_counters[port_name]["binding_full"] += 1
            snoop_counters[port_name]["ack"] += 1
            return {
                "action": "binding_full",
                "msg_type": mtype,
                "xid": xid,
                "chaddr": chaddr,
                "yiaddr": yiaddr,
                "lease": truncated,
            }
        bindings[ip_key] = {
            "mac": chaddr,
            "port": access_port,
            "expires": t + truncated,
        }
        del requests[req_key]
        snoop_counters[port_name]["ack"] += 1
        return {
            "action": "ack",
            "msg_type": mtype,
            "xid": xid,
            "chaddr": chaddr,
            "yiaddr": yiaddr,
            "lease": truncated,
            "requested_lease": lease,
            "truncated": lease > max_lease,
            "bound": True,
            "refreshed": existing is not None,
            "expires": t + truncated,
        }
    # 客户端报文
    if mtype == DHCP_MSG_DISCOVER:
        requests[req_key] = port_name
        snoop_counters[port_name]["discover"] += 1
        return {
            "action": "discover",
            "msg_type": mtype,
            "xid": xid,
            "chaddr": chaddr,
        }
    if mtype == DHCP_MSG_REQUEST:
        requests[req_key] = port_name
        snoop_counters[port_name]["request"] += 1
        return {
            "action": "request",
            "msg_type": mtype,
            "xid": xid,
            "chaddr": chaddr,
            "ciaddr": info["ciaddr"],
        }
    if mtype == DHCP_MSG_RELEASE:
        # 仅在来源端口、MAC、VLAN 均与绑定匹配时删除
        ciaddr = info["ciaddr"]
        removed = False
        entry = bindings.get((vlan, ciaddr))
        if (
            entry is not None
            and entry["mac"] == chaddr
            and entry["port"] == port_name
        ):
            del bindings[(vlan, ciaddr)]
            removed = True
        snoop_counters[port_name]["release"] += 1
        return {
            "action": "release",
            "msg_type": mtype,
            "xid": xid,
            "chaddr": chaddr,
            "ciaddr": ciaddr,
            "removed": removed,
        }
    if mtype == DHCP_MSG_DECLINE:
        snoop_counters[port_name]["decline"] += 1
        return {
            "action": "decline",
            "msg_type": mtype,
            "xid": xid,
            "chaddr": chaddr,
            "ciaddr": info["ciaddr"],
        }
    # INFORM
    snoop_counters[port_name]["inform"] += 1
    return {
        "action": "inform",
        "msg_type": mtype,
        "xid": xid,
        "chaddr": chaddr,
        "ciaddr": info["ciaddr"],
    }


