    DHCP_MSG_DECLINE: "decline",
    DHCP_MSG_ACK: "ack",
    DHCP_MSG_NAK: "nak",
    DHCP_MSG_RELEASE: "release",
    DHCP_MSG_INFORM: "inform",
}
# 每端口 DHCP 分类计数固定键序（malformed 单列，其余按报文/裁决互斥一类）
DHCP_CLASSIFICATION_KEYS = (
    "malformed_dhcp",
