def validate_dhcp_snoop_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != DHCP_SNOOP_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # 七键与 stp-decode（stp-check）完全一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, max_frame = (
        validate_stp_check_config(
            {key: config[key] for key in STP_CHECK_CONFIG_KEYS}
        )
    )
    dhcp = config["dhcp"]
    if not isinstance(dhcp, dict) or frozenset(dhcp) != DHCP_KEYS:
        raise InvalidInput("bad dhcp")
    trusted_ports = dhcp["trusted_ports"]
    if not isinstance(trusted_ports, list):
        raise InvalidInput("bad dhcp trusted_ports")
    name_set = {port["name"] for port in ports}
    for name in trusted_ports:
        if not isinstance(name, str) or name not in name_set:
            raise InvalidInput("bad dhcp trusted port")
    if len(set(trusted_ports)) != len(trusted_ports):  # 端口名不重复
        raise InvalidInput("bad dhcp trusted_ports")
    capacity_doc = dhcp["binding_capacity"]
    if not isinstance(capacity_doc, list):
        raise InvalidInput("bad dhcp binding_capacity")
    capacity = {}
    for item in capacity_doc:
        if (
            not isinstance(item, dict)
            or frozenset(item) != frozenset(("vlan", "limit"))
        ):
            raise InvalidInput("bad dhcp binding_capacity")
        vlan = item["vlan"]
        limit = item["limit"]
        if not _valid_vlan_id(vlan):
            raise InvalidInput("bad dhcp binding_capacity vlan")
        if not _is_int(limit) or limit < 0:
            raise InvalidInput("bad dhcp binding_capacity limit")
        if vlan in capacity:  # 每 VLAN 至多一项
            raise InvalidInput("bad dhcp binding_capacity vlan")
        capacity[vlan] = limit
    max_lease = dhcp["max_lease"]
    if not _is_int(max_lease) or max_lease <= 0:
        raise InvalidInput("bad dhcp max_lease")
    return (
        bridges, links, delay, bridge, ports, age, max_frame,
        tuple(trusted_ports), capacity, max_lease,
    )


def _ipv4_dotted(octets):
    return ".".join(str(octet) for octet in octets)


def _ipv4_unicast_lease(ip_text):
    """绑定地址有效性：首字节 1..223、排除 127 环回段。"""
    octets = tuple(int(part) for part in ip_text.split("."))
    return 1 <= octets[0] <= 223 and octets[0] != 127


def _dhcp_locate(raw, ethertype_offset):
    """在单层 802.1Q 帧内定位未分片 IPv4/UDP 上目的端口为 67/68 的报文。

    返回 None：帧不“形似 DHCP”（非 IPv4、IPv4 头容纳不了 UDP、分片、非
    UDP、目的端口既非 67 也非 68），调用方完全沿用既有语义；
    返回 ("shaped", header_len, total_length, udp_len, src, dst) 表示已形似
    DHCP，后续任一层校验失败即 malformed_dhcp。
    """
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 20 or payload[0] >> 4 != 4:
        return None
    ihl = payload[0] & 0x0F
    if ihl < 5:
        return None
    header_len = ihl * 4
    if len(payload) < header_len + 8:  # 容纳不了定长 UDP 头
        return None
    if (payload[6] << 8 | payload[7]) & 0x3FFF:  # 任何分片都不识别
        return None
    if payload[9] != IP_PROTOCOL_UDP:
        return None
    dst_port = (payload[header_len + 2] << 8) | payload[header_len + 3]
    if dst_port not in (BOOTP_SERVER_PORT, BOOTP_CLIENT_PORT):
        return None
    total_length = (payload[2] << 8) | payload[3]
    udp_len = (payload[header_len + 4] << 8) | payload[header_len + 5]
    return (
        "shaped", header_len, total_length, udp_len,
        bytes(payload[12:16]), bytes(payload[16:20]),
    )


def _parse_dhcp_frame(raw, ethertype_offset):
    """识别并校验单层 802.1Q 上的 IPv4/UDP/BOOTP/DHCP。

    返回 None（非形似 DHCP）、("invalid",)（形似但协议长度、IPv4 首部校验
    和、magic cookie 或关键选项非法）或 ("ok", info)。
    """
    located = _dhcp_locate(raw, ethertype_offset)
    if located is None:
        return None
    _, header_len, total_length, udp_len, src_ip, dst_ip = located
    payload = raw[ethertype_offset + 2:-4]
    # 自此帧形似 DHCP：以下任一非法均为 malformed_dhcp
    if _internet_checksum(payload[:header_len]) != 0:  # IPv4 首部校验和
        return ("invalid",)
    # IPv4 总长度：容纳 IP 头与 UDP，且不超过实际载荷
    if total_length < header_len + 8 or total_length > len(payload):
        return ("invalid",)
    # UDP 长度：至少 8 字节且完整位于 IPv4 总长度内
    if udp_len < 8 or header_len + udp_len > total_length:
        return ("invalid",)
    bootp_len = udp_len - 8
    bootp_msg = payload[header_len + 8:header_len + udp_len]
    if len(bootp_msg) != bootp_len or bootp_len < BOOTP_MIN_LEN:
        # BOOTP 报文短于 300 字节即非法；长度以 UDP 长度字段为准
        return ("invalid",)
    op = bootp_msg[0]
    if op not in (BOOTP_OP_REQUEST, BOOTP_OP_REPLY):
        return ("invalid",)
    if bootp_msg[1] != 1:  # htype 以太网
        return ("invalid",)
    hlen = bootp_msg[2]
    if hlen != 6:
        return ("invalid",)
    if bootp_msg[3] != 0:  # hops 须为 0（无中继）
        return ("invalid",)
    chaddr = bytes(bootp_msg[28:34])
    if not any(chaddr) or chaddr[0] & 1:  # 客户端 MAC 须为非零单播
        return ("invalid",)
    if any(bootp_msg[34:44]):  # chaddr 余 10 字节须为零
        return ("invalid",)
    xid = int.from_bytes(bootp_msg[4:8], "big")
    ciaddr = bytes(bootp_msg[12:16])
    yiaddr = bytes(bootp_msg[16:20])
    siaddr = bytes(bootp_msg[20:24])
    if bootp_msg[BOOTP_FIXED_LEN:BOOTP_FIXED_LEN + 4] != BOOTP_MAGIC_COOKIE:
        return ("invalid",)
    options = bootp_msg[BOOTP_FIXED_LEN + 4:]
    msg_types = []
    lease = None
    index = 0
    closed = False
    while index < len(options):
        code = options[index]
        if code == 0:  # PAD
            index += 1
            continue
        if code == DHCP_OPT_END:
            if any(options[index + 1:]):  # END 后只允许零填充
                return ("invalid",)
            closed = True
            break
        if index + 2 > len(options):
            return ("invalid",)
        length = options[index + 1]
        value_start = index + 2
        value_end = value_start + length
        if value_end > len(options):
            return ("invalid",)
        value = options[value_start:value_end]
        if code == DHCP_OPT_MSG_TYPE:
            if length != 1 or value[0] not in (
                DHCP_CLIENT_MESSAGES | DHCP_SERVER_MESSAGES
            ):
                return ("invalid",)
            msg_types.append(value[0])
        elif code == DHCP_OPT_LEASE_TIME:
            if length != 4:
                return ("invalid",)
            candidate = int.from_bytes(value, "big")
            if candidate == 0:  # 租期为 0 非法
                return ("invalid",)
            lease = candidate
        index = value_end
    if not closed or len(msg_types) != 1:  # 恰一个消息类型选项且 END 闭合
        return ("invalid",)
    msg_type = msg_types[0]
    dst_port = (payload[header_len + 2] << 8) | payload[header_len + 3]
    # op 与 UDP 方向必须一致：客户端发往 67，服务器发往 68
    if op == BOOTP_OP_REQUEST:
        if msg_type not in DHCP_CLIENT_MESSAGES:
            return ("invalid",)
        if dst_port != BOOTP_SERVER_PORT:
            return ("invalid",)
    else:
        if msg_type not in DHCP_SERVER_MESSAGES:
            return ("invalid",)
        if dst_port != BOOTP_CLIENT_PORT:
            return ("invalid",)
    return (
        "ok",
        {
            "msg_type": msg_type,
            "xid": xid,
            "chaddr": _format_mac(chaddr),
            "ciaddr": _ipv4_dotted(ciaddr),
            "yiaddr": _ipv4_dotted(yiaddr),
            "siaddr": _ipv4_dotted(siaddr),
            "lease": lease,
        },
    )


def _dhcp_stp_context(bridges, links, bridge_name, ports, by_id, port_link):
    """构造 converge/forwarding_ports/port_status 闭包（仿真与预演共用）。"""
    by_name = {port["name"]: port for port in ports}
    previous = {}
    since = {}
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay_global[0]
            ):
                result.add(name)
        return result

    def port_status(name, t):
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay_global[0]:
                state = "discarding"
            elif elapsed < 2 * delay_global[0]:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"
        return True, state

    return converge, forwarding_ports, port_status


def _dhcp_frame_gate(item, by_name, max_frame, port_status, t):
    """帧合法性、VLAN 准入与 STP 状态闸门（仿真与预演共用）。

    返回 ("skip",)（坏帧/准入拒绝/非 forwarding，调用方各自按既有语义统
    计）或 ("pass", vlan, ethertype_offset, raw)。
    """
    _, _, port_name, raw = item
    length = len(raw)
    if length < FRAME_CHECK_RUNT_LENGTH or length > max_frame:
        return ("skip",)
    if raw[-4:] != (
        zlib.crc32(raw[:-4]) & 0xFFFFFFFF
    ).to_bytes(4, "little"):
        return ("skip",)
    if raw[12:14] == FRAME_DECODE_TAG:
        vlan = ((raw[14] << 8) | raw[15]) & 0x0FFF
        ingress = by_name[port_name]
        if ingress["mode"] == "access" or vlan not in ingress["allowed"]:
            return ("skip",)
        ethertype_offset = 16
    else:
        vlan = by_name[port_name]["pvid"]
        ethertype_offset = 12
    _, state = port_status(port_name, t)
    if state != "forwarding":
        return ("skip",)
    return ("pass", vlan, ethertype_offset, raw)


def _dhcp_client_verdict(t, port_name, vlan, info, bindings, requests):
    """客户端报文控制面状态机，返回 (verdict, snoop)。"""
    mtype = info["msg_type"]
    xid = info["xid"]
    chaddr = info["chaddr"]
    base = {"msg": DHCP_MSG_NAMES[mtype], "xid": xid, "chaddr": chaddr}
    if mtype in (DHCP_MSG_DISCOVER, DHCP_MSG_REQUEST):
        # 按 xid、chaddr、VLAN 记录接入口；同键重发仅刷新接入口
        requests[(vlan, xid, chaddr)] = port_name
        if mtype == DHCP_MSG_DISCOVER:
            return "discover", dict(base)
        snoop = dict(base)
        snoop["ciaddr"] = info["ciaddr"]
        return "request", snoop
    if mtype == DHCP_MSG_RELEASE:
        ciaddr = info["ciaddr"]
        removed = False
        entry = bindings.get((vlan, ciaddr))
        if (
            entry is not None
            and entry["mac"] == chaddr
            and entry["port"] == port_name
        ):
            # RELEASE 仅在来源端口、MAC、VLAN 均匹配时删除绑定
            del bindings[(vlan, ciaddr)]
            removed = True
        snoop = dict(base)
        snoop["ciaddr"] = ciaddr
        snoop["removed"] = removed
        return "release", snoop
    snoop = dict(base)
    snoop["ciaddr"] = info["ciaddr"]
    return DHCP_MSG_NAMES[mtype], snoop  # decline / inform


def _dhcp_server_verdict(
    t, port_name, vlan, info, bindings, requests, trusted_set, capacity,
    max_lease,
):
    """服务器报文控制面状态机，返回 (verdict, snoop)。"""
    mtype = info["msg_type"]
    xid = info["xid"]
    chaddr = info["chaddr"]
    base = {"msg": DHCP_MSG_NAMES[mtype], "xid": xid, "chaddr": chaddr}
    if port_name not in trusted_set:
        # 非受信任端口发来的 OFFER/ACK/NAK：untrusted_server，不改状态
        return "untrusted_server", dict(base)
    if mtype == DHCP_MSG_OFFER:
        snoop = dict(base)
        snoop["yiaddr"] = info["yiaddr"]
        return "offer", snoop
    if mtype == DHCP_MSG_NAK:
        matched = requests.pop((vlan, xid, chaddr), None) is not None
        snoop = dict(base)
        snoop["matched"] = matched
        return "nak", snoop
    # ACK：仅受信任端口返回且匹配请求（xid、chaddr、VLAN）才建绑定
    access_port = requests.get((vlan, xid, chaddr))
    yiaddr = info["yiaddr"]
    lease = info["lease"]
    if (
        access_port is None
        or yiaddr == "0.0.0.0"
        or not _ipv4_unicast_lease(yiaddr)
        or lease is None
    ):
        # 无匹配请求、地址无效或无租期：按既有数据面转发，不建绑定
        snoop = dict(base)
        snoop["yiaddr"] = yiaddr
        snoop["lease"] = lease
        snoop["bound"] = False
        return "ack", snoop
    ip_key = (vlan, yiaddr)
    existing = bindings.get(ip_key)
    if existing is not None and existing["mac"] != chaddr:
        # 活动 IP 已被同 VLAN 的其他 MAC 占用：binding_conflict 并丢弃
        snoop = dict(base)
        snoop["yiaddr"] = yiaddr
        snoop["owner_mac"] = existing["mac"]
        return "binding_conflict", snoop
    effective = min(lease, max_lease)  # 租期超过上限截断
    if existing is None:
        cap = capacity.get(vlan)
        if cap is not None:
            used = sum(1 for bvlan, _ in bindings if bvlan == vlan)
            if used >= cap:  # 新绑定超过每 VLAN 容量：不建绑定
                snoop = dict(base)
                snoop["yiaddr"] = yiaddr
                snoop["lease"] = effective
                return "binding_full", snoop
    bindings[ip_key] = {
        "mac": chaddr,
        "port": access_port,  # 绑定接入口，而非受信任的服务器口
        "expires": t + effective,
    }
    del requests[(vlan, xid, chaddr)]
    snoop = dict(base)
    snoop["yiaddr"] = yiaddr
    snoop["lease"] = effective
    snoop["bound"] = True
    snoop["refreshed"] = existing is not None
    snoop["truncated"] = lease > max_lease
    snoop["port"] = access_port
    snoop["expires"] = t + effective
    return "ack", snoop


def dhcp_snoop_work(
    bridges, links, delay, bridge_name, ports, max_frame, trusted_ports,
    capacity, max_lease, events, limit,
):
    """dhcp-snoop-decode 工作量无副作用预演。

    逐事件（链路项与帧项合计）累计 1 + 端口数 P + 处理前活动绑定数 B
    （先老化 expires<=t 再计数）。预演完整复算帧合法性、VLAN 准入、STP
    状态与 DHCP 绑定机以保证 B 与正式仿真逐事件一致，但使用 links 的浅
    拷贝，不修改正式输入，也不产生结果/统计。等于上限合法，首次超过抛
    DhcpWorkLimit。
    """
    global delay_global
    preview_links = [dict(link) for link in links]  # 不改动正式 links
    by_id = {link["id"]: link for link in preview_links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}
    for link in preview_links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    delay_global = [delay]
    converge, forwarding_ports, port_status = _dhcp_stp_context(
        bridges, preview_links, bridge_name, ports, by_id, port_link
    )
    trusted_set = set(trusted_ports)
    bindings = {}
    requests = {}
    P = len(ports)

    def purge(t):
        for key in [k for k, e in bindings.items() if e["expires"] <= t]:
            del bindings[key]

    converge(0)
    work = 0
    for item in events:
        t = item[1]
        purge(t)
        work += 1 + P + len(bindings)
        if work > limit:
            raise DhcpWorkLimit
        if item[0] == "link":
            _, _, lid, up = item
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            if old_forwarding - forwarding_ports(t):
                # 与正式仿真一致：链路事件不删除基于租期的绑定/请求
                pass
            continue
        gate = _dhcp_frame_gate(item, by_name, max_frame, port_status, t)
        if gate[0] == "skip":
            continue
        _, vlan, ethertype_offset, raw = gate
        if (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        ) != IPV4_ETHER_TYPE:
            continue
        parsed = _parse_dhcp_frame(raw, ethertype_offset)
        if parsed is None or parsed[0] == "invalid":
            continue
        info = parsed[1]
        if info["msg_type"] in DHCP_SERVER_MESSAGES:
            _dhcp_server_verdict(
                t, item[2], vlan, info, bindings, requests, trusted_set,
                capacity, max_lease,
            )
        else:
            _dhcp_client_verdict(
                t, item[2], vlan, info, bindings, requests
            )


delay_global = [0]


def dhcp_snoop_decode(
    bridges, links, delay, bridge_name, ports, age, max_frame,
    trusted_ports, capacity, max_lease, events, observer=None,
):
    """在 stp-decode 转发/学习/统计语义上增加 DHCPv4 Snooping。

    非 DHCP 帧完全沿用既有 VLAN、STP、帧合法性与转发语义。形似 DHCP 但
    IPv4/UDP/BOOTP/DHCP 任一层非法时固定 malformed_dhcp、空 ports、计
    drop，不学习 FDB、不记录请求或绑定。非受信任端口发来的
    OFFER/ACK/NAK 固定 untrusted_server 并丢弃（不学习 FDB）。合法客户端
    DISCOVER/REQUEST 按 (vlan,xid,chaddr) 记录接入口；仅受信任端口返回且
    匹配请求的 ACK 才按 yiaddr、客户端 MAC、VLAN、接入口与租期建立或刷新
    绑定，租期超过 max_lease 截断；每事件先老化 expires<=t 的绑定；NAK
    清除匹配请求；RELEASE 仅在来源端口、MAC、VLAN 均匹配时删除绑定。活动
    IP 已被同 VLAN 其他 MAC 占用时 binding_conflict 丢弃；新绑定超过每
    VLAN 容量时 binding_full，ACK 仍按既有数据面转发但不建绑定。

    每个帧结果固定键序 t/action/ports/snoop（非 DHCP 帧 snoop 为 null）；
    末态 bindings 按 VLAN、IP、MAC、端口排序；ports 内每端口追加固定键序
    的 DHCP 分类计数。observer 语义同 stp-check。
    """
    global delay_global
    delay_global = [delay]
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    converge, forwarding_ports, port_status = _dhcp_stp_context(
        bridges, links, bridge_name, ports, by_id, port_link
    )
    fdb = {}  # (vlan, mac) -> [port, seen]
    bindings = {}  # (vlan, ip) -> {"mac", "port", "expires"}
    requests = {}  # (vlan, xid, chaddr) -> access_port
    trusted_set = set(trusted_ports)
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    snoop_counters = {
        port["name"]: {key: 0 for key in DHCP_CLASSIFICATION_KEYS}
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    if observer is not None:
        observer["items"] = []

    def eligible_names(t, vlan, ingress):
        return [
            port["name"]
            for port in ports
            if vlan in port["allowed"]
            and port["name"] != ingress
            and port_status(port["name"], t) == (True, "forwarding")
        ]

    def emit(t, action, out_ports, snoop, vlan=None):
        out = []
        for name in out_ports:
            port_stats[name]["tx"] += 1
            if vlan is not None:
                vlan_stats[vlan]["tx"] += 1
            out.append(
                {
                    "name": name,
                    "vlan": (
                        None if vlan in by_name[name]["untagged"] else vlan
                    ),
                }
            )
        entry = {"t": t, "action": action, "ports": out, "snoop": snoop}
        results.append(entry)
        if observer is not None:
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )

    def data_egress(t, port_name, vlan, dst, fdb):
        """合法 DHCP 帧的数据面转发：完全沿用既有泛洪/单播语义。"""
        is_group = int(dst[:2], 16) & 1
        eligible = eligible_names(t, vlan, port_name)
        if is_group:
            return eligible
        hit = fdb.get((vlan, dst))
        if hit is not None and hit[0] != port_name:
            target = hit[0]
            target_up, target_state = port_status(target, t)
            if (
                target_up
                and target_state == "forwarding"
                and vlan in by_name[target]["allowed"]
            ):
                return [target]
            return []
        if hit is None:
            return eligible
        return []

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        for key in [  # 每个事件前先老化 expires<=t 的绑定
            key for key, entry in bindings.items() if entry["expires"] <= t
        ]:
            del bindings[key]
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            for name in old_forwarding - forwarding_ports(t):
                # FDB 清理沿用 stp-decode；绑定与待处理请求仅按租期/
                # RELEASE/NAK 消亡，链路事件不删除
                for key in [k for k, (p, _) in fdb.items() if p == name]:
                    del fdb[key]
            if observer is not None:
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, raw = item
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        tagged = raw[12:14] == FRAME_DECODE_TAG
        ethertype_offset = 16 if tagged else 12
        ethertype = (
            (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        )
        length = len(raw)
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif raw[-4:] != (
            zlib.crc32(raw[:-4]) & 0xFFFFFFFF
        ).to_bytes(4, "little"):
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1
        if cls != "good":
            port_stats[port_name]["drop"] += 1
            emit(t, "drop", [], None)
            continue
        if tagged:
            vlan = ((raw[14] << 8) | raw[15]) & 0x0FFF
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        else:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        if rejected:
            port_stats[port_name]["drop"] += 1
            emit(t, "drop", [], None)
            continue
        vlan_stats[vlan]["rx"] += 1
        up_flag, state = port_status(port_name, t)
        # DHCP 识别仅在 forwarding 状态进行；discarding/learning 上的形似
        # DHCP 帧不触发 malformed 分类（learning 仍学习 FDB 但不转发）
        parsed = None
        if state == "forwarding" and ethertype == IPV4_ETHER_TYPE:
            parsed = _parse_dhcp_frame(raw, ethertype_offset)
        if parsed is not None and parsed[0] == "invalid":
            # 形似 DHCP 但报文非法：丢弃，不学习 FDB、请求或绑定
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
            snoop_counters[port_name]["malformed_dhcp"] += 1
            emit(
                t, "malformed_dhcp", [],
                {"verdict": "malformed_dhcp"}, vlan=vlan,
            )
            continue
        egress = []
        action = "drop"
        snoop = None
        if state == "learning":
            fdb[(vlan, src)] = [port_name, t]
        elif state == "forwarding":
            fdb[(vlan, src)] = [port_name, t]
            if parsed is not None:
                info = parsed[1]
                if info["msg_type"] in DHCP_SERVER_MESSAGES:
                    verdict, snoop = _dhcp_server_verdict(
                        t, port_name, vlan, info, bindings, requests,
                        trusted_set, capacity, max_lease,
                    )
                else:
                    verdict, snoop = _dhcp_client_verdict(
                        t, port_name, vlan, info, bindings, requests
                    )
                snoop_counters[port_name][verdict] += 1
                if verdict in ("untrusted_server", "binding_conflict"):
                    # 控制面拒绝：丢弃，不转发（FDB 已在上方学习与否的处理：
                    # 这两类不学习 FDB）
                    fdb.pop((vlan, src), None)
                    port_stats[port_name]["drop"] += 1
                    vlan_stats[vlan]["drop"] += 1
                    emit(t, verdict, [], snoop, vlan=vlan)
                    continue
                # 其余合法裁决（含 binding_full）按既有数据面转发
                egress = data_egress(t, port_name, vlan, dst, fdb)
                action = verdict if verdict in (
                    "discover", "request", "offer", "ack", "nak",
                    "release", "decline", "inform",
                ) else None
                if action is None:  # binding_full：动作取数据面动作
                    action = "flood" if (
                        int(dst[:2], 16) & 1
                    ) else ("unicast" if egress else "drop")
                else:
                    # 合法 DHCP 的转发动作仍按数据面泛洪/单播/丢弃呈现
                    action = "flood" if (
                        int(dst[:2], 16) & 1
                    ) else ("unicast" if egress else "drop")
            else:
                is_group = int(dst[:2], 16) & 1
                eligible = eligible_names(t, vlan, port_name)
                if is_group:
                    egress = eligible
                    action = "flood"
                else:
                    hit = fdb.get((vlan, dst))
                    if hit is not None and hit[0] != port_name:
                        target = hit[0]
                        target_up, target_state = port_status(target, t)
                        if (
                            target_up
                            and target_state == "forwarding"
                            and vlan in by_name[target]["allowed"]
                        ):
                            egress = [target]
                            action = "unicast"
                    elif hit is None:
                        egress = eligible
                        action = "flood"
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        emit(t, action, egress, snoop, vlan=vlan)
    port_order = {port["name"]: index for index, port in enumerate(ports)}
    bindings_out = []
    for (vlan, ip), entry in sorted(
        bindings.items(),
        key=lambda item: (
            item[0][0],
            tuple(int(part) for part in item[0][1].split(".")),
            tuple(int(part, 16) for part in item[1]["mac"].split(":")),
            port_order[item[1]["port"]],
        ),
    ):
        bindings_out.append(
            {
                "vlan": vlan,
                "ip": ip,
                "mac": entry["mac"],
                "port": entry["port"],
                "expires": entry["expires"],
            }
        )
    output = {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
                "good": port_stats[port["name"]]["good"],
                "runt": port_stats[port["name"]]["runt"],
                "giant": port_stats[port["name"]]["giant"],
                "alignment": port_stats[port["name"]]["alignment"],
                "bad_fcs": port_stats[port["name"]]["bad_fcs"],
                **{
                    key: snoop_counters[port["name"]][key]
                    for key in DHCP_CLASSIFICATION_KEYS
                },
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
        "bindings": bindings_out,
    }
    return output


