        or frozenset(config) != FORWARD_CAPACITY_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    ports, age, static = validate_forward_static_config(
        {"ports": config["ports"], "age": config["age"],
         "static": config["static"]}
